const maxConvertedBlockTime = `-- name: MaxConvertedBlockTime :one
SELECT (b.a_ms + (1 + b.b) * rb.t0_ms)::float8 AS t0_epoch_ms
FROM raw_block rb
JOIN boot b ON b.dongle_id = rb.dongle_id AND b.boot_generation = rb.boot_generation AND b.boot_id = rb.boot_id
WHERE rb.dongle_id = $1 AND rb.marker IS NULL AND rb.seq >= $2 AND rb.seq <= $3
  AND b.time_source IS NOT NULL
ORDER BY 1 DESC
LIMIT 1
`

// Hora absoluta (ms) do t0 do bloco mais recente já convertido, entre os blocos de seq em [from_seq, to_seq].
// Janela curta de propósito: raw_block é percorrido por seq, e a busca só precisa dos últimos blocos.
func (q *Queries) MaxConvertedBlockTime(ctx context.Context, dongleID int32, fromSeq int64, toSeq int64) (float64, error) {
	row := q.db.QueryRow(ctx, maxConvertedBlockTime, dongleID, fromSeq, toSeq)
	var t0_epoch_ms float64
	err := row.Scan(&t0_epoch_ms)
	return t0_epoch_ms, err
}

const nextBootFirstSeq = `-- name: NextBootFirstSeq :one
SELECT first_seq FROM boot WHERE dongle_id = $1 AND first_seq > $2 ORDER BY first_seq LIMIT 1
`

func (q *Queries) NextBootFirstSeq(ctx context.Context, dongleID int32, afterSeq *int64) (*int64, error) {
	row := q.db.QueryRow(ctx, nextBootFirstSeq, dongleID, afterSeq)
	var first_seq *int64
	err := row.Scan(&first_seq)
	return first_seq, err
}

const notifyTripCreated = `-- name: NotifyTripCreated :exec
SELECT pg_notify('trip_pending', $1::text)
`

func (q *Queries) NotifyTripCreated(ctx context.Context, payload string) error {
	_, err := q.db.Exec(ctx, notifyTripCreated, payload)
	return err
}

const notifyTripPending = `-- name: NotifyTripPending :exec
SELECT pg_notify('trip_pending', '')
`

func (q *Queries) NotifyTripPending(ctx context.Context) error {
	_, err := q.db.Exec(ctx, notifyTripPending)
	return err
}

const resolveTripGeneration = `-- name: ResolveTripGeneration :one
UPDATE gold.trip t SET boot_generation = g.generation
FROM (SELECT max(b.boot_generation) AS generation FROM boot b WHERE b.dongle_id = $2 AND b.boot_id = $3) g
WHERE t.trip_id = $1 AND t.boot_generation IS NULL AND g.generation IS NOT NULL
RETURNING t.boot_generation
`

// A API grava boot_generation nula quando o boot ainda não existe; vale a maior geração que tem o boot_id.
func (q *Queries) ResolveTripGeneration(ctx context.Context, tripID uuid.UUID, dongleID int32, bootID int32) (*int32, error) {
	row := q.db.QueryRow(ctx, resolveTripGeneration, tripID, dongleID, bootID)
	var boot_generation *int32
	err := row.Scan(&boot_generation)
	return boot_generation, err
}

const saveTripResult = `-- name: SaveTripResult :exec
UPDATE gold.trip SET
  status = 'ready', calculation_version = $1, calculated_at = $2,
  first_seq = $3, last_seq = $4, calculated_through_seq = $5,
  provisional = $6, recalc_pending = false
WHERE trip_id = $7
`

type SaveTripResultParams struct {
	CalculationVersion   *string
	CalculatedAt         *time.Time
	FirstSeq             *int64
	LastSeq              *int64
	CalculatedThroughSeq *int64
	Provisional          bool
	TripID               uuid.UUID
}

func (q *Queries) SaveTripResult(ctx context.Context, arg SaveTripResultParams) error {
	_, err := q.db.Exec(ctx, saveTripResult,
		arg.CalculationVersion,
		arg.CalculatedAt,
		arg.FirstSeq,
		arg.LastSeq,
		arg.CalculatedThroughSeq,
		arg.Provisional,
		arg.TripID,
	)
	return err
}

const takeRecalcTrip = `-- name: TakeRecalcTrip :one
SELECT trip_id, trip_category, driver_name, driver_name_normalized, fuel, dongle_id, entry_type, boot_generation, boot_id, interval_start, interval_end, status, target_seq, first_seq, last_seq, calculated_through_seq, provisional, recalc_pending, calculation_version, created_at, calculated_at, excluded_at FROM gold.trip
WHERE status = 'ready' AND recalc_pending
ORDER BY created_at
LIMIT 1
FOR UPDATE SKIP LOCKED
`

func (q *Queries) TakeRecalcTrip(ctx context.Context) (GoldTrip, error) {
	row := q.db.QueryRow(ctx, takeRecalcTrip)
	var i GoldTrip
	err := row.Scan(
		&i.TripID,
		&i.TripCategory,
		&i.DriverName,
		&i.DriverNameNormalized,
		&i.Fuel,
		&i.DongleID,
		&i.EntryType,
		&i.BootGeneration,
		&i.BootID,
		&i.IntervalStart,
		&i.IntervalEnd,
		&i.Status,
		&i.TargetSeq,
		&i.FirstSeq,
		&i.LastSeq,
		&i.CalculatedThroughSeq,
		&i.Provisional,
		&i.RecalcPending,
		&i.CalculationVersion,
		&i.CreatedAt,
		&i.CalculatedAt,
		&i.ExcludedAt,
	)
	return i, err
}

